uang tamu}'::text[] kw,10 o union all select 'cleaning_kitchen' k,'cleaning' c,'清潔廚房' tz,'Bersihkan dapur' ti,'清潔爐頭、枱面同洗碗盆，倒垃圾。' iz,'Bersihkan kompor, meja, wastafel; buang sampah.' ii,'scheduled' tt,'11:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{廚房,dapur}'::text[] kw,20 o union all select 'cleaning_bathroom' k,'cleaning' c,'清潔浴室' tz,'Bersihkan kamar mandi' ti,'清潔廁所、洗手盆同淋浴間，補充紙巾。' iz,'Bersihkan toilet, wastafel, dan shower; isi tisu.' ii,'scheduled' tt,'14:00'::time tm,'{"rule":"weekly"}'::jsonb r,'normal' p,false s,'{浴室,kamar mandi}'::text[] kw,30 o union all select 'cleaning_floor' k,'cleaning' c,'掃地拖地' tz,'Sapu dan pel lantai' ti,'全屋掃地後拖地，注意濕滑。' iz,'Sapu seluruh rumah lalu pel; hati-hati lantai basah.' ii,'scheduled' tt,'09:30'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{拖地,pel}'::text[] kw,40 o union all select 'cleaning_windows' k,'cleaning' c,'抹窗' tz,'Bersihkan jendela' ti,'抹內窗同窗台，唔好站出窗外。' iz,'Bersihkan jendela dalam dan ambang; jangan berdiri di luar jendela.' ii,'adhoc' tt,'10:00'::time tm,'{"rule":"none"}'::jsonb r,'normal' p,true s,'{抹窗,jendela}'::text[] kw,50 o union all select 'cleaning_trash' k,'cleaning' c,'倒垃圾' tz,'Buang sampah' ti,'將垃圾桶袋紮好拎落樓下垃圾房。' iz,'Ikat kantong sampah dan buang ke tempat sampah gedung.' ii,'scheduled' tt,'20:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{垃圾,sampah}'::text[] kw,60 o union all select 'laundry_wash' k,'laundry' c,'洗衫' tz,'Cuci baju' ti,'分開顏色同白衫，按標籤溫度清洗。' iz,'Pisahkan warna dan putih; cuci sesuai label suhu.' ii,'scheduled' tt,'09:00'::time tm,'{"rule":"weekdays"}'::jsonb r,'normal' p,false s,'{洗衫,cuci}'::text[] kw,10 o union all select 'laundry_dry' k,'laundry' c,'晾衫／乾衣' tz,'Jemur / keringkan baju' ti,'晾衫或放入乾衣機，完成後執好。' iz,'Jemur atau masukkan dryer; rapikan setelah selesai.' ii,'scheduled' tt,'11:00'::time tm,'{"rule":"weekdays"}'::jsonb r,'normal' p,false s,'{晾衫,jemur}'::text[] kw,20 o union all select 'laundry_iron' k,'laundry' c,'熨衫' tz,'Setrika baju' ti,'熨恤衫同校服，注意溫