asi majikan.' ii,'scheduled' tt,'06:00'::time tm,'{"rule":"daily"}'::jsonb r,'high' p,true s,'{嬰兒,bayi,奶}'::text[] kw,10 o union all select 'baby_diaper' k,'baby' c,'換尿片' tz,'Ganti popok' ti,'按需要換尿片，洗手同清潔雙手。' iz,'Ganti popok sesuai kebutuhan; cuci tangan dengan bersih.' ii,'scheduled' tt,'08:00'::time tm,'{"rule":"daily"}'::jsonb r,'high' p,true s,'{尿片,popok}'::text[] kw,20 o union all select 'baby_bath' k,'baby' c,'替嬰兒沖涼' tz,'Mandikan bayi' ti,'用合適水溫替嬰兒沖涼，全程托穩。必須僱主在場或確認。' iz,'Mandikan bayi dengan suhu air yang tepat; selalu dukung bayi. Harus dengan majikan atau dikonfirmasi.' ii,'scheduled' tt,'19:00'::time tm,'{"rule":"daily"}'::jsonb r,'high' p,true s,'{沖涼,mandi,bayi}'::text[] kw,30 o union all select 'baby_sterilise' k,'baby' c,'消毒奶樽' tz,'Sterilkan botol susu' ti,'清洗同消毒奶樽同奶咀。' iz,'Cuci dan sterilkan botol serta dot.' ii,'scheduled' tt,'21:00'::time tm,'{"rule":"daily"}'::jsonb r,'high' p,true s,'{奶樽,botol}'::text[] kw,40 o union all select 'child_school_prep' k,'childcare' c,'準備返學用品' tz,'Siapkan perlengkapan sekolah' ti,'整書包、水壺同小食，確認功課放入。' iz,'Siapkan tas, botol minum, dan bekal; pastikan PR masuk tas.' ii,'scheduled' tt,'07:30'::time tm,'{"rule":"weekdays"}'::jsonb r,'normal' p,false s,'{返學,sekolah}'::text[] kw,10 o union all select 'child_homework' k,'childcare' c,'陪做功課' tz,'Dampingi mengerjakan PR' ti,'陪伴小朋友做功課，唔好代做答案。' iz,'Dampingi anak mengerjakan PR; jangan mengerjakan jawaban untuknya.' ii,'scheduled' tt,'17:00'::time tm,'{"rule":"weekdays"}'::jsonb r,'normal' p,false s,'{功課,PR}'::text[] kw,20 o union all select 'child_bath' k,'childcare' c,'幫小朋友沖涼' tz,'Bantu anak mandi' ti,'協助沖涼同換睡衣，注意防滑。' iz,'Bantu mandi dan ganti piyama; hati-hati lantai licin.' ii,'scheduled' tt,'19:30'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,true s,'{沖涼,mandi}'::text[] kw,30 o union all select 'child_play' k,'childcare' c,'陪玩同看管' tz,'Temani bermain dan mengawasi' ti,'喺安全範圍內陪玩，唔好讓小朋友單獨近窗或廚房。' iz,'Temani bermain di area aman; jangan biarkan anak sendiri dekat jendela atau dapur.' ii,'adhoc' tt,'15:00'::time tm,'{"rule":"none"}'::jsonb r,'high' p,true s,'{看管,awasi}'::text[] kw,40 o union all select 'child_snack' k,'childcare' c,'準備小食' tz,'Siapkan camilan' ti,'按指示準備健康小食，注意過敏。' iz,'Siapkan camilan sehat sesuai instruksi; perhatikan alergi.' ii,'scheduled' tt,'16:00'::time tm,'{"rule":"weekdays"}'::jsonb r,'normal' p,true s,'{小食,camilan,過敏}'::text[] kw,50 o union all select 'transport_school' k,'transport' c,'接送返學放學' tz,'Antar jemput sekolah' ti,'按時間接送小朋友返學放學，確認安全過馬路。' iz,'Antar jemput anak ke sekolah tepat waktu; pastikan aman saat menyeberang.' ii,'scheduled' tt,'07:45'::time tm,'{"rule":"weekdays"}'::jsonb r,'high' p,true s,'{接送,antar jemput}'::text[] kw,10 o union all select 'transport_activity' k,'transport' c,'接送興趣班' tz,'Antar jemput les / kegiatan' ti,'按時間地點接送，到達後通知僱主。' iz,'Antar jemput sesuai jadwal dan lokasi; beri tahu majikan saat tiba.' ii,'scheduled' tt,'16:30'::time tm,'{"rule":"weekly"}'::jsonb r,'normal' p,false s,'{興趣班,les}'::text[] kw,20 o union all select 'transport_errand' k,'transport' c,'外出辦事' tz,'Keluar untuk urusan' ti,'按指示外出辦事，保管好鎖匙同收據。' iz,'Keluar sesuai instruksi; jaga kunci dan struk dengan baik.' ii,'adhoc' tt,'14:00'::time tm,'{"rule":"none"}'::jsonb r,'normal' p,false s,'{外出,keluar}'::text[] kw,30 o union all select 'elderly_meal' k,'elderly' c,'協助長者用餐' tz,'Bantu lansia makan' ti,'協助長者用餐，注意吞嚥安全。必須僱主確認特別指示。' iz,'Bantu lansia makan; perhatikan keamanan menelan. Konfirmasi instruksi khusus dengan majikan.' ii,'scheduled' tt,'12:00'::time tm,'{"rule":"daily"}'::jsonb r,'high' p,true s,'{長者,lansia}'::text[] kw,10 o union all select 'elderly_med_remind' k,'elderly' c,'提醒服藥時間' tz,'Ingatkan waktu minum obat' ti,'只提醒時間，唔好自行決定藥量。藥物相關必須僱主確認。' iz,'Hanya mengingatkan waktu; jangan menentukan dosis sendiri. Obat harus dikonfirmasi majikan.' ii,'scheduled' tt,'08:00'::time tm,'{"rule":"daily"}'::jsonb r,'urgent' p,true s,'{藥,obat}'::text[] kw,20 o union all select 'elderly_walk' k,'elderly' c,'陪長者散步' tz,'Temani lansia jalan-jalan' ti,'短距離慢行，注意路面同休息。' iz,'Jalan pelan jarak pendek; perhatikan jalan dan istirahat.' ii,'scheduled' tt,'17:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,true s,'{散步,jalan}'::text[] kw,30 o union all select 'pets_feed_dog' k,'pets' c,'餵狗' tz,'Beri makan anjing' ti,'按份量餵狗同換清水。' iz,'Beri makan anjing sesuai porsi dan ganti air bersih.' ii,'scheduled' tt,'08:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{狗,anjing}'::text[] kw,10 o union all select 'pets_feed_cat' k,'pets' c,'餵貓' tz,'Beri makan kucing' ti,'按份量餵貓、換水同清理貓砂。' iz,'Beri makan kucing, ganti air, dan bersihkan pasir kucing.' ii,'scheduled' tt,'08:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{貓,kucing}'::text[] kw,20 o union all select 'pets_walk' k,'pets' c,'遛狗' tz,'Jalan-jalan dengan anjing' ti,'用牽繩帶狗落街，清理排泄物。' iz,'Gunakan tali; bersihkan kotoran anjing.' ii,'scheduled' tt,'07:00'::time tm,'{"rule":"daily"}'::jsonb r,'normal' p,false s,'{遛狗,jalan anjing}'::text[] kw,30 o union all select 'maint_ac_filter' k,'maintenance' c,'清潔冷氣隔塵網' tz,'Bersihkan filter AC' ti,'關閉冷氣後拆洗隔塵網，乾透先裝返。' iz,'Matikan AC, cuci filter, keringkan sebelum dipasang kembali.' ii,'scheduled' tt,'10:00'::time tm,'{"rule":"monthly"}'::jsonb r,'normal' p,false s,'{冷氣,AC}'::text[] kw,10 o union all select 'maint_plants' k,'maintenance' c,'澆花' tz,'Siram tanaman' ti,'按需要為室內植物澆水，唔好過多。' iz,'Siram tanaman dalam ruangan sesuai kebutuhan; jangan berlebihan.' ii,'scheduled' tt,'09:00'::time tm,'{"rule":"daily"}'::jsonb r,'low' p,false s,'{花,tanaman}'::text[] kw,20 o union all select 'maint_organise' k,'maintenance' c,'執屋整理' tz,'Rapikan rumah' ti,'整理雜物、收納玩具同雜誌。' iz,'Rapikan barang, mainan, dan majalah.' ii,'scheduled' tt,'15:00'::time tm,'{"rule":"weekly"}'::jsonb r,'normal' p,false s,'{執屋,rapikan}'::text[] kw,30 o union all select 'maint_check_supplies' k,'maintenance' c,'檢查耗材存量' tz,'Cek stok kebutuhan' ti,'檢查廁紙、清潔劑等同耗材，列出要補充項目。' iz,'Cek tisu, pembersih, dll.; catat yang perlu dibeli.' ii,'scheduled' tt,'11:00'::ti